package cz.nowass.dispenser.crypto

import cz.nowass.dispenser.ble.protocol.BleProtocol
import cz.nowass.dispenser.crypto.TestNative.hex
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * test-vectors/ble_handshake_v1.txt (Dispenser framing, generated by the independent Rust snow tool;
 * NOT conformance vectors) through the Android JNI binding (host build of the same sources):
 * every phone and device frame, the handshake hash and every encrypted frame byte for byte; the
 * Kotlin BLE codec re-encodes every HS frame identically; the negative records fail as recorded.
 * Fixed ephemerals and the responder role come from the test-only hooks.
 */
class HandshakeVectorsTest {
    private val noise = TestNative.load()
    private val records = TestNative.records(TestNative.vectorFile("ble_handshake_v1.txt"))

    private class Transcript(val hs: Map<String, String>, val frames: List<Pair<String, Map<String, String>>>, val hash: ByteArray) {
        val id = hs.getValue("id")
        val xx = hs["pattern"] == "XXpsk3"
        val purpose = hs.getValue("purpose").toInt()
        fun b(k: String) = hex(hs.getValue(k))
        fun namePayload(): ByteArray = b("name").let { byteArrayOf(it.size.toByte()) + it }
    }

    private val transcripts: List<Transcript> = records.filter { it.first == "hs" }.map { (_, hs) ->
        val id = hs.getValue("id")
        Transcript(hs, records.filter { (r, kv) -> (r == "frame" || r == "enc") && kv["id"] == id },
            hex(records.first { (r, kv) -> r == "hash" && kv["id"] == id }.second.getValue("handshake_hash")))
    }

    private fun phone(t: Transcript, prologue: ByteArray = t.b("prologue"), psk: ByteArray? = if (t.xx) t.b("psk") else null,
                      pinned: ByteArray? = if (t.xx) null else t.b("device_static_pub"), static: ByteArray = t.b("phone_static")) =
        NativeNoiseTestHooks.handshake(t.xx, true, prologue, static, pinned, psk, t.b("phone_ephemeral"))

    private fun device(t: Transcript) =
        NativeNoiseTestHooks.handshake(t.xx, false, t.b("prologue"), t.b("device_static"), null, if (t.xx) t.b("psk") else null, t.b("device_ephemeral"))

    /** Runs a transcript; returns the transport ciphers (phone, device) and the frame count. */
    private fun run(t: Transcript): Triple<TransportCiphers, TransportCiphers, Int> {
        val p = phone(t)
        val d = device(t)
        var pc: TransportCiphers? = null
        var dc: TransportCiphers? = null
        var n = 0
        for ((rec, kv) in t.frames) {
            val bytes = hex(kv.getValue("bytes"))
            val d2p = kv["dir"] == "d2p"
            if (rec == "frame") {
                val f = BleProtocol.decode(bytes)
                val fields = checkNotNull(f.fields)
                assertEquals(0x02, f.header.type) // HS
                assertArrayEquals("${t.id}: codec round trip", bytes, BleProtocol.encode(f.header.type, f.header.flags, f.header.txn, fields))
                val noiseField = fields.getValue("noise") as ByteArray
                if (!d2p) assertEquals(t.purpose, (fields["purpose"] as Number).toInt())
                val payload = if (!d2p && kv["n"] == "3") t.namePayload() else ByteArray(0)
                val (w, r) = if (d2p) d to p else p to d
                assertArrayEquals("${t.id} frame ${kv["n"]}", noiseField, w.writeMessage(payload))
                assertArrayEquals(payload, r.readMessage(noiseField))
                n++
                if (p.isFinished) {
                    assertTrue(d.isFinished)
                    assertArrayEquals("${t.id} hash", t.hash, p.handshakeHash())
                    assertArrayEquals(t.hash, d.handshakeHash())
                    assertArrayEquals(t.b("device_static_pub"), p.remoteStatic())
                    assertArrayEquals(t.b("phone_static_pub"), d.remoteStatic())
                    pc = p.split()
                    dc = d.split()
                }
            } else {
                val header = hex(kv.getValue("header"))
                val plain = hex(kv.getValue("plain"))
                val (w, r) = if (d2p) dc!! to pc!! else pc!! to dc!!
                assertArrayEquals("${t.id} enc ${kv["n"]}", bytes.copyOfRange(8, bytes.size), w.encrypt(header, plain))
                assertArrayEquals(plain, r.decrypt(bytes.copyOf(8), bytes.copyOfRange(8, bytes.size)))
                n++
            }
        }
        return Triple(pc!!, dc!!, n)
    }

    @Test
    fun transcripts_byte_for_byte() {
        assertEquals(listOf("claim_a", "session_a", "add_b", "session_b", "recovery_c", "session_c"), transcripts.map { it.id })
        var frames = 0
        for (t in transcripts) {
            val (pc, dc, n) = run(t)
            pc.close()
            dc.close()
            frames += n
        }
        assertEquals(33, frames)
    }

    /** The production initiator (CSPRNG ephemerals) interoperates with the device side of every transcript's inputs. */
    @Test
    fun production_initiator_completes_every_purpose() {
        for (t in transcripts) {
            val purpose = Purpose.entries.first { it.wire == t.purpose }
            val pskS = if (t.xx) SecretBytes.wrap(t.b("psk")) else null
            val init = SecretBytes.wrap(t.b("phone_static")).use { s ->
                noise.newInitiator(purpose, t.b("prologue"), s, if (t.xx) null else t.b("device_static_pub"), pskS)
            }
            pskS?.close()
            val d = device(t)
            val m1 = init.writeMessage()
            d.readMessage(m1)
            init.readMessage(d.writeMessage())
            if (t.xx) d.readMessage(init.writeMessage(t.namePayload()))
            assertTrue(init.isFinished && d.isFinished)
            assertArrayEquals(init.handshakeHash(), d.handshakeHash())
            val pc = init.split()
            val dc = d.split()
            val header = byteArrayOf(1, 0, 0x7E, 0x08, 4, 0, 16, 0)
            assertArrayEquals(ByteArray(0), dc.decrypt(header, pc.encrypt(header, ByteArray(0))))
            pc.close()
            dc.close()
            // the same inputs with a different ephemeral give a different first message
            val again = SecretBytes.wrap(t.b("phone_static")).use { s ->
                (if (t.xx) SecretBytes.wrap(t.b("psk")) else null).use { p ->
                    noise.newInitiator(purpose, t.b("prologue"), s, if (t.xx) null else t.b("device_static_pub"), p)
                }
            }
            assertFalse(again.writeMessage().contentEquals(m1))
            again.close()
        }
    }

    @Test
    fun negative_records() {
        val negs = records.filter { it.first == "neg" }.map { it.second }
        assertEquals(10, negs.size)
        for (neg in negs) {
            val t = transcripts.first { it.id == neg["base"] }
            val bytes = hex(neg.getValue("bytes"))
            val frame = neg.getValue("frame").toInt()
            val id = neg.getValue("id")
            when (neg["expect"]) {
                "device_rejects" -> {
                    val d = device(t)
                    if (frame == 3) {
                        d.readMessage(BleProtocol.decode(hex(t.frames[0].second.getValue("bytes"))).fields!!.getValue("noise") as ByteArray)
                        d.writeMessage()
                    }
                    val msg = BleProtocol.decode(bytes).fields!!.getValue("noise") as ByteArray
                    if (id == "session_unknown_phone_key") {
                        d.readMessage(msg) // Noise accepts: the device's authorization refuses the key
                        assertFalse(d.remoteStatic().contentEquals(t.b("phone_static_pub")))
                    } else {
                        assertNoiseRejects(id) { d.readMessage(msg) }
                    }
                    d.close()
                }
                "phone_rejects" -> if (frame == 2) {
                    val wrong = hex(neg.getValue("change").substringAfter('='))
                    val p = phone(t, prologue = wrong)
                    p.writeMessage()
                    assertNoiseRejects(id) { p.readMessage(BleProtocol.decode(bytes).fields!!.getValue("noise") as ByteArray) }
                    p.close()
                } else {
                    val (pc, dc, _) = runHandshakeOnly(t)
                    assertNoiseRejects(id) { pc.decrypt(bytes.copyOf(8), bytes.copyOfRange(8, bytes.size)) }
                    pc.close(); dc.close()
                }
                "device_drops" -> {
                    val (pc, dc, _) = runHandshakeOnly(t)
                    if (bytes.size >= 8 + 16) {
                        assertNoiseRejects(id) { dc.decrypt(bytes.copyOf(8), bytes.copyOfRange(8, bytes.size)) }
                    } else {
                        // the codec refuses the frame before decryption (length mismatch)
                        try { BleProtocol.parseHeader(bytes); BleProtocol.decode(bytes); fail("$id: decoded") } catch (_: Exception) {}
                    }
                    pc.close(); dc.close()
                }
                "phone_aborts" -> {
                    val p = phone(t)
                    p.writeMessage()
                    p.readMessage(BleProtocol.decode(bytes).fields!!.getValue("noise") as ByteArray)
                    val inv = Invitation(byteArrayOf(0, 0, 0, 0, 0, 1), hex(neg.getValue("change").substringAfter('=')), SecretBytes.wrap(ByteArray(16)), 600, 0)
                    assertFalse(id, inv.matchesDeviceKey(p.remoteStatic()))
                    assertArrayEquals(t.b("device_static_pub"), p.remoteStatic())
                    inv.close(); p.close()
                }
                else -> fail("unknown expectation ${neg["expect"]}")
            }
        }
    }

    private fun runHandshakeOnly(t: Transcript): Triple<TransportCiphers, TransportCiphers, Int> {
        val p = phone(t)
        val d = device(t)
        d.readMessage(p.writeMessage())
        p.readMessage(d.writeMessage())
        if (t.xx) d.readMessage(p.writeMessage(t.namePayload()))
        return Triple(p.split(), d.split(), 0)
    }

    private fun assertNoiseRejects(id: String, block: () -> Unit) {
        try {
            block()
            fail("$id: accepted")
        } catch (e: NoiseException) {
            assertTrue(id, e.isAuthenticationFailure)
        }
    }
}
